//! Differential tests against the R `survival` reference fixtures in
//! `test/r/fixtures/*.json` (generated by `test/r/generate_fixtures.R`, see
//! `test/r/README.md`).
//!
//! Only kernels reachable without Python are exercised here: the Kaplan-Meier
//! engine (`surv_analysis::compute_survfitkm`), `survdiff2`,
//! `regression::coxph::coxph_fit` and its residual methods,
//! `regression::parametric_survival::survreg`, `concordance::concordance_index`
//! and a few `data_prep` helpers.  The Python suite
//! (`python/tests/test_r_fixtures.py`) covers the remaining topics.
//!
//! Each topic is one `#[test]` that walks every fixture case and aspect it can
//! express.  Failures of cases listed in [`KNOWN_FAILURES`] are reported but
//! tolerated; a listed case that passes fails the test with a message asking
//! for its removal, so the list is a strict burndown.
#![cfg(test)]

use crate::regression::coxph::{CoxPHFit, coxph_fit};
use crate::regression::parametric_survival::survreg;
use crate::surv_analysis::logrank_components::survdiff2;
use crate::surv_analysis::survfitkm_module::compute_survfitkm_with_timefix;
use crate::surv_analysis::{KaplanMeierConfig, SurvFitKMOutput};
use serde_json::Value;
use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::PathBuf;

/// Relative tolerance for coefficients, curves, residuals and linear predictors.
/// Vectors and matrices also get an absolute floor of `rtol * max|expected|`
/// (see [`assert_vec`]).
const RTOL_COEF: f64 = 1e-8;
/// Relative tolerance for variances, standard errors, test statistics, p-values.
const RTOL_VAR: f64 = 1e-6;

