// ---------------------------------------------------------------------------
// Fixture access
// ---------------------------------------------------------------------------

fn manifest_path(relative: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(relative)
}

fn load_topic(topic: &str) -> Value {
    let path = manifest_path(&format!("test/r/fixtures/{topic}.json"));
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|err| panic!("cannot read {}: {err}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|err| panic!("invalid JSON in {topic}: {err}"))
}

fn is_r_error(value: &Value) -> bool {
    value.get("r_error").is_some()
}

/// Decode one fixture number: `null` -> NaN (R `NA`), the strings `"NaN"`,
/// `"Inf"`, `"-Inf"` -> the corresponding float.
fn num(value: &Value) -> Result<f64, String> {
    match value {
        Value::Null => Ok(f64::NAN),
        Value::Number(n) => n.as_f64().ok_or_else(|| "non-f64 number".to_string()),
        Value::Bool(b) => Ok(if *b { 1.0 } else { 0.0 }),
        Value::String(s) => match s.as_str() {
            "NaN" => Ok(f64::NAN),
            "Inf" => Ok(f64::INFINITY),
            "-Inf" => Ok(f64::NEG_INFINITY),
            other => Err(format!("not a number: {other:?}")),
        },
        other => Err(format!("not a number: {other}")),
    }
}

fn nums(value: &Value) -> Result<Vec<f64>, String> {
    match value {
        Value::Array(items) => items.iter().map(num).collect(),
        Value::Null => Err("missing numeric vector".to_string()),
        other => Ok(vec![num(other)?]),
    }
}

fn matrix(value: &Value) -> Result<Vec<Vec<f64>>, String> {
    match value {
        Value::Array(rows) => rows
            .iter()
            .map(|row| match row {
                Value::Array(_) => nums(row),
                other => Ok(vec![num(other)?]),
            })
            .collect(),
        other => Err(format!("not a matrix: {other}")),
    }
}

/// Values of an R named vector stored as a JSON object.  `serde_json` maps
/// do not preserve insertion order, so the generator also stores the names in
/// R order under `<key>_names`; `names` is that array.
fn named_values(value: &Value, names: &Value) -> Result<Vec<f64>, String> {
    match value {
        Value::Object(map) => match names.as_array() {
            Some(order) => order
                .iter()
                .map(|name| {
                    let key = name.as_str().ok_or("non-string name")?;
                    num(map
                        .get(key)
                        .ok_or_else(|| format!("missing coefficient {key}"))?)
                })
                .collect(),
            None => Err("named vector without an order array".to_string()),
        },
        Value::Array(items) if items.is_empty() => Ok(Vec::new()),
        other => Err(format!("not a named vector: {other}")),
    }
}

fn names_of(value: &Value) -> Vec<&str> {
    value
        .as_array()
        .map(|items| items.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default()
}

fn text(value: &Value) -> Option<&str> {
    value.as_str()
}

fn is_true(value: &Value) -> bool {
    value.as_bool().unwrap_or(false)
}

// ---------------------------------------------------------------------------
// Comparison helpers
// ---------------------------------------------------------------------------

/// `|actual - expected| <= atol + rtol * |expected|`, with NaN matching only
/// NaN and infinities matching only the same infinity.
fn close(actual: f64, expected: f64, rtol: f64, atol: f64) -> bool {
    if expected.is_nan() {
        return actual.is_nan();
    }
    if expected.is_infinite() {
        return actual == expected;
    }
    if !actual.is_finite() {
        return false;
    }
    (actual - expected).abs() <= atol + rtol * expected.abs()
}

/// Largest finite magnitude of a vector or matrix, the scale of the
/// absolute floor used when comparing it.
fn max_abs<'a>(values: impl IntoIterator<Item = &'a f64>) -> f64 {
    values
        .into_iter()
        .filter(|v| v.is_finite())
        .fold(0.0, |acc, v| acc.max(v.abs()))
}

/// Compare a vector element-wise.  Like R's `all.equal`, the tolerance is
/// relative to the size of the whole vector: an element is accepted when
/// `|a - e| <= rtol * max(|e|, max|expected|)`, so floating-point noise
/// around zero (`1e-17` against an exact `0`) inside an otherwise matching
/// vector is not a mismatch.
fn assert_vec(actual: &[f64], expected: &[f64], rtol: f64, path: &str) -> Result<(), String> {
    assert_vec_within(actual, expected, rtol, rtol * max_abs(expected), path)
}

fn assert_vec_within(
    actual: &[f64],
    expected: &[f64],
    rtol: f64,
    atol: f64,
    path: &str,
) -> Result<(), String> {
    if actual.len() != expected.len() {
        return Err(format!(
            "{path}: length {} differs from expected {}",
            actual.len(),
            expected.len()
        ));
    }
    for (idx, (a, e)) in actual.iter().zip(expected).enumerate() {
        if !close(*a, *e, rtol, atol) {
            return Err(format!(
                "{path}[{idx}]: {a:?} != {e:?} (rtol={rtol:e}, atol={atol:e})"
            ));
        }
    }
    Ok(())
}

/// Compare a matrix; the absolute floor is scaled to the whole matrix.
fn assert_matrix(
    actual: &[Vec<f64>],
    expected: &[Vec<f64>],
    rtol: f64,
    path: &str,
) -> Result<(), String> {
    if actual.len() != expected.len() {
        return Err(format!(
            "{path}: {} rows, expected {}",
            actual.len(),
            expected.len()
        ));
    }
    let atol = rtol * max_abs(expected.iter().flatten());
    for (idx, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert_vec_within(a, e, rtol, atol, &format!("{path}[{idx}]"))?;
    }
    Ok(())
}

/// A scalar has no vector to scale against: pure relative tolerance.
fn assert_scalar(actual: f64, expected: f64, rtol: f64, path: &str) -> Result<(), String> {
    if close(actual, expected, rtol, 0.0) {
        Ok(())
    } else {
        Err(format!(
            "{path}: {actual:?} != {expected:?} (rtol={rtol:e})"
        ))
    }
}

/// Outcome of one (case, aspect) check.
enum Outcome {
    Pass,
    Fail(String),
    Unsupported(String),
}

fn outcome(result: Result<(), String>) -> Outcome {
    match result {
        Ok(()) => Outcome::Pass,
        Err(message) if message.starts_with("unsupported:") => Outcome::Unsupported(message),
        Err(message) => Outcome::Fail(message),
    }
}

fn unsupported<T>(reason: impl Into<String>) -> Result<T, String> {
    Err(format!("unsupported: {}", reason.into()))
}

/// When `R_FIXTURES_COLLECT` names a file, append one JSON line per check
/// (`{"id", "kind", "message"}`) so the burndown list can be rebuilt.
fn collect_outcome(id: &str, outcome: &Outcome) {
    let Ok(path) = std::env::var("R_FIXTURES_COLLECT") else {
        return;
    };
    let (kind, message) = match outcome {
        Outcome::Pass => ("pass", String::new()),
        Outcome::Fail(message) => ("mismatch", message.clone()),
        Outcome::Unsupported(message) => ("missing feature", message.clone()),
    };
    let line = serde_json::json!({"id": id, "kind": kind, "message": message});
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
    {
        use std::io::Write;
        let _ = writeln!(file, "{line}");
    }
}

/// Collects outcomes for a topic and applies the KNOWN_FAILURES contract.
struct Report {
    topic: String,
    checked: usize,
    failures: Vec<String>,
    unexpected_passes: Vec<String>,
    known: Vec<String>,
}

impl Report {
    fn new(topic: &str) -> Self {
        Self {
            topic: topic.to_string(),
            checked: 0,
            failures: Vec::new(),
            unexpected_passes: Vec::new(),
            known: Vec::new(),
        }
    }

    fn known_reason(&self, id: &str) -> Option<&'static str> {
        let case_id = id.rsplit_once('/').map(|(head, _)| head).unwrap_or(id);
        KNOWN_FAILURES
            .iter()
            .find(|(key, _)| *key == id || *key == case_id)
            .map(|(_, reason)| *reason)
    }

    fn record(&mut self, case: &str, aspect: &str, result: Result<(), String>) {
        let id = format!("{}/{}/{}", self.topic, case, aspect);
        self.checked += 1;
        let known = self.known_reason(&id);
        let outcome = outcome(result);
        collect_outcome(&id, &outcome);
        match (outcome, known) {
            (Outcome::Pass, None) => {}
            (Outcome::Pass, Some(reason)) => self.unexpected_passes.push(format!(
                "{id} passes; remove it from KNOWN_FAILURES ({reason})"
            )),
            (Outcome::Fail(message) | Outcome::Unsupported(message), Some(_)) => {
                self.known.push(format!("{id}: {message}"))
            }
            (Outcome::Fail(message) | Outcome::Unsupported(message), None) => {
                self.failures.push(format!("{id}: {message}"))
            }
        }
    }

    fn finish(self) {
        let mut summary = String::new();
        let _ = writeln!(
            summary,
            "{}: {} checks, {} failures, {} known failures",
            self.topic,
            self.checked,
            self.failures.len(),
            self.known.len()
        );
        for line in &self.known {
            let _ = writeln!(summary, "  known: {line}");
        }
        for line in &self.failures {
            let _ = writeln!(summary, "  FAIL: {line}");
        }
        for line in &self.unexpected_passes {
            let _ = writeln!(summary, "  XPASS: {line}");
        }
        println!("{summary}");
        assert!(
            self.failures.is_empty() && self.unexpected_passes.is_empty(),
            "{summary}"
        );
    }
}

// ---------------------------------------------------------------------------
// Data frames: bundled CSV datasets and inline fixture frames
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
enum Column {
    Num(Vec<f64>),
    /// String column with its R factor levels (empty when the column is
    /// character rather than factor; levels are then the sorted unique values).
    Str(Vec<Option<String>>, Vec<String>),
}

impl Column {
    fn len(&self) -> usize {
        match self {
            Column::Num(values) => values.len(),
            Column::Str(values, _) => values.len(),
        }
    }

    fn subset(&self, rows: &[usize]) -> Column {
        match self {
            Column::Num(values) => Column::Num(rows.iter().map(|&i| values[i]).collect()),
            Column::Str(values, levels) => Column::Str(
                rows.iter().map(|&i| values[i].clone()).collect(),
                levels.clone(),
            ),
        }
    }

    fn levels(&self) -> Vec<String> {
        match self {
            Column::Num(values) => {
                let mut unique: Vec<f64> = values.iter().copied().filter(|v| !v.is_nan()).collect();
                unique.sort_by(f64::total_cmp);
                unique.dedup();
                unique.iter().map(|v| format_r_number(*v)).collect()
            }
            Column::Str(values, levels) => {
                if !levels.is_empty() {
                    return levels.clone();
                }
                let mut unique: Vec<String> = values.iter().flatten().cloned().collect();
                unique.sort();
                unique.dedup();
                unique
            }
        }
    }

    /// Label of row `i` as R would print it in a strata name.
    fn label(&self, i: usize) -> Option<String> {
        match self {
            Column::Num(values) => (!values[i].is_nan()).then(|| format_r_number(values[i])),
            Column::Str(values, _) => values[i].clone(),
        }
    }

    fn numeric(&self, name: &str) -> Result<Vec<f64>, String> {
        match self {
            Column::Num(values) => Ok(values.clone()),
            Column::Str(..) => unsupported(format!("column {name} is not numeric")),
        }
    }
}

fn format_r_number(value: f64) -> String {
    if value.fract() == 0.0 && value.abs() < 1e15 {
        format!("{}", value as i64)
    } else {
        format!("{value}")
    }
}

#[derive(Clone, Debug, Default)]
struct Frame {
    columns: Vec<(String, Column)>,
}

impl Frame {
    fn get(&self, name: &str) -> Result<&Column, String> {
        self.columns
            .iter()
            .find(|(column, _)| column == name)
            .map(|(_, column)| column)
            .ok_or_else(|| format!("column {name:?} not found"))
    }

    fn nrow(&self) -> usize {
        self.columns.first().map_or(0, |(_, column)| column.len())
    }

    fn subset(&self, rows: &[usize]) -> Frame {
        Frame {
            columns: self
                .columns
                .iter()
                .map(|(name, column)| (name.clone(), column.subset(rows)))
                .collect(),
        }
    }

    fn set_levels(&mut self, name: &str, levels: Vec<String>) {
        if let Some((_, Column::Str(_, current))) =
            self.columns.iter_mut().find(|(column, _)| column == name)
        {
            *current = levels;
        }
    }
}

/// Minimal CSV reader for `src/datasets/data/*.csv` (quoted fields, `NA`).
fn parse_csv(text: &str) -> Result<Frame, String> {
    let mut lines = text.lines().filter(|line| !line.trim().is_empty());
    let header = lines.next().ok_or("empty CSV")?;
    let names = split_csv_line(header);
    let mut raw: Vec<Vec<Option<String>>> = vec![Vec::new(); names.len()];
    for line in lines {
        let fields = split_csv_line(line);
        if fields.len() != names.len() {
            return Err(format!(
                "CSV row has {} fields, header {}",
                fields.len(),
                names.len()
            ));
        }
        for (column, field) in raw.iter_mut().zip(fields) {
            column.push(if field == "NA" || field.is_empty() {
                None
            } else {
                Some(field)
            });
        }
    }
    let columns = names
        .into_iter()
        .zip(raw)
        .filter(|(name, _)| name != "rownames")
        .map(|(name, values)| {
            let parsed: Option<Vec<f64>> = values
                .iter()
                .map(|value| match value {
                    None => Some(f64::NAN),
                    Some(text) => text.parse::<f64>().ok(),
                })
                .collect();
            let column = match parsed {
                Some(numbers) => Column::Num(numbers),
                None => Column::Str(values, Vec::new()),
            };
            (name, column)
        })
        .collect();
    Ok(Frame { columns })
}

fn split_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                current.push('"');
                chars.next();
            }
            '"' => in_quotes = !in_quotes,
            ',' if !in_quotes => fields.push(std::mem::take(&mut current)),
            _ => current.push(ch),
        }
    }
    fields.push(current);
    fields
}

/// Candidate CSV file names for an R dataset name.
fn dataset_files(name: &str) -> Vec<String> {
    match name {
        "nafld1" => vec!["nafld1.csv".into(), "nafld.csv".into()],
        other => vec![format!("{other}.csv")],
    }
}

fn load_dataset(name: &str) -> Result<Frame, String> {
    for file in dataset_files(name) {
        let path = manifest_path(&format!("src/datasets/data/{file}"));
        if let Ok(text) = std::fs::read_to_string(&path) {
            return parse_csv(&text);
        }
    }
    unsupported(format!("no bundled CSV for dataset {name}"))
}

fn inline_frame(frame: &Value) -> Result<Frame, String> {
    let factors = &frame["factors"];
    let mut columns = Vec::new();
    for (name, values) in frame["columns"]
        .as_object()
        .ok_or("inline frame without columns")?
    {
        let items = values.as_array().ok_or("column is not an array")?;
        let numeric: Result<Vec<f64>, String> = items.iter().map(num).collect();
        let column = match numeric {
            Ok(values) if !items.iter().any(|v| v.is_string() && num(v).is_err()) => {
                Column::Num(values)
            }
            _ => {
                let levels = factors[name]
                    .as_array()
                    .map(|levels| {
                        levels
                            .iter()
                            .filter_map(|v| v.as_str().map(str::to_string))
                            .collect()
                    })
                    .unwrap_or_default();
                Column::Str(
                    items
                        .iter()
                        .map(|v| v.as_str().map(str::to_string))
                        .collect(),
                    levels,
                )
            }
        };
        columns.push((name.clone(), column));
    }
    Ok(Frame { columns })
}

/// The data frame of a case (bundled dataset or inline frame, subset applied).
fn case_frame(doc: &Value, case: &Value) -> Result<Frame, String> {
    let mut frame = if let Some(reference) = text(&case["data_ref"]) {
        inline_frame(&doc["data"][reference])?
    } else if let Some(dataset) = text(&case["dataset"]) {
        let mut frame = load_dataset(dataset)?;
        if let Some(factors) = case["factors"].as_object() {
            for (name, levels) in factors {
                let levels = levels
                    .as_array()
                    .map(|items| {
                        items
                            .iter()
                            .filter_map(|v| v.as_str().map(str::to_string))
                            .collect()
                    })
                    .unwrap_or_default();
                frame.set_levels(name, levels);
            }
        }
        frame
    } else {
        return unsupported("case has no data");
    };
    if let Some(rows) = case["rows"].as_array() {
        let indices: Vec<usize> = rows
            .iter()
            .map(|row| row.as_u64().map(|r| r as usize - 1).ok_or("bad row index"))
            .collect::<Result<_, _>>()?;
        frame = frame.subset(&indices);
    }
    Ok(frame)
}

// ---------------------------------------------------------------------------
// A small R formula reader (enough for the fixture formulas)
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct Response {
    start: Option<Vec<f64>>,
    time: Vec<f64>,
    status: Vec<i32>,
}

/// Evaluate a `Surv(...)` response.  Supports `Surv(time, status)`,
/// `Surv(time, status == v)`, `Surv(start, stop, status)` and the R rule that a
/// 1/2 coded status means 2 = event.
fn response(formula: &str, frame: &Frame) -> Result<Response, String> {
    let lhs = formula.split('~').next().ok_or("formula without ~")?.trim();
    let inner = lhs
        .strip_prefix("Surv(")
        .and_then(|rest| rest.strip_suffix(')'))
        .ok_or_else(|| format!("unsupported: harness: response {lhs:?}"))?;
    let args: Vec<&str> = inner.split(',').map(str::trim).collect();
    if args.iter().any(|arg| arg.starts_with("type")) {
        return unsupported("harness: Surv(type=) responses");
    }
    let status_expr = *args.last().ok_or("empty Surv()")?;
    let status = status_column(status_expr, frame)?;
    match args.len() {
        2 => Ok(Response {
            start: None,
            time: frame.get(args[0])?.numeric(args[0])?,
            status,
        }),
        3 => Ok(Response {
            start: Some(frame.get(args[0])?.numeric(args[0])?),
            time: frame.get(args[1])?.numeric(args[1])?,
            status,
        }),
        _ => unsupported(format!("harness: Surv() with {} arguments", args.len())),
    }
}

fn status_column(expr: &str, frame: &Frame) -> Result<Vec<i32>, String> {
    if let Some((name, value)) = expr.split_once("==") {
        let column = frame.get(name.trim())?;
        let target = value.trim().trim_matches('"');
        return Ok((0..column.len())
            .map(|i| i32::from(column.label(i).as_deref() == Some(target)))
            .collect());
    }
    let values = frame.get(expr)?.numeric(expr)?;
    let max = values.iter().copied().fold(f64::MIN, f64::max);
    let min = values.iter().copied().fold(f64::MAX, f64::min);
    if min == 1.0 && max == 2.0 {
        return Ok(values.iter().map(|&v| i32::from(v == 2.0)).collect());
    }
    Ok(values.iter().map(|&v| i32::from(v != 0.0)).collect())
}

fn rhs_terms(formula: &str) -> Vec<String> {
    formula
        .split_once('~')
        .map(|(_, rhs)| rhs)
        .unwrap_or("")
        .split('+')
        .map(|term| term.trim().to_string())
        .filter(|term| !term.is_empty())
        .collect()
}

/// Rows grouped by the levels of a single column, in R's strata order.
fn groups_by_column(column: &Column) -> Vec<(String, Vec<usize>)> {
    column
        .levels()
        .into_iter()
        .map(|level| {
            let rows = (0..column.len())
                .filter(|&i| column.label(i).as_deref() == Some(level.as_str()))
                .collect();
            (level, rows)
        })
        .collect()
}

/// Treatment-contrast design matrix for `+`-separated terms: numeric
/// columns, `log(x)`, factor/character columns (R level order), `factor(x)`.
/// Returns (column names, rows, strata codes, offset).
struct Design {
    names: Vec<String>,
    rows: Vec<Vec<f64>>,
    strata: Option<Vec<i32>>,
    offset: Option<Vec<f64>>,
}

fn design(formula: &str, frame: &Frame) -> Result<Design, String> {
    let n = frame.nrow();
    let mut names = Vec::new();
    let mut columns: Vec<Vec<f64>> = Vec::new();
    let mut strata = None;
    let mut offset = None;
    for term in rhs_terms(formula) {
        if term == "1" {
            continue;
        }
        if let Some(inner) = term
            .strip_prefix("strata(")
            .and_then(|t| t.strip_suffix(')'))
        {
            let column = frame.get(inner)?;
            let levels = column.levels();
            let codes = (0..n)
                .map(|i| {
                    column
                        .label(i)
                        .and_then(|label| levels.iter().position(|l| *l == label))
                        .map_or(-1, |p| p as i32)
                })
                .collect();
            strata = Some(codes);
            continue;
        }
        if let Some(inner) = term
            .strip_prefix("offset(")
            .and_then(|t| t.strip_suffix(')'))
        {
            offset = Some(frame.get(inner)?.numeric(inner)?);
            continue;
        }
        if term.starts_with("cluster(") {
            continue;
        }
        if term.contains(':') || term.contains('*') || term.contains("tt(") {
            return unsupported(format!("harness: formula term {term}"));
        }
        if let Some(inner) = term.strip_prefix("log(").and_then(|t| t.strip_suffix(')')) {
            let values = frame.get(inner)?.numeric(inner)?;
            names.push(term.clone());
            columns.push(values.iter().map(|v| v.ln()).collect());
            continue;
        }
        let (column_name, force_factor) = match term
            .strip_prefix("factor(")
            .and_then(|t| t.strip_suffix(')'))
        {
            Some(inner) => (inner.to_string(), true),
            None => (term.clone(), false),
        };
        let column = frame.get(&column_name)?;
        match column {
            Column::Num(values) if !force_factor => {
                names.push(term.clone());
                columns.push(values.clone());
            }
            _ => {
                let levels = column.levels();
                for level in levels.iter().skip(1) {
                    names.push(format!("{term}{level}"));
                    columns.push(
                        (0..n)
                            .map(|i| f64::from(column.label(i).as_deref() == Some(level.as_str())))
                            .collect(),
                    );
                }
            }
        }
    }
    let rows = (0..n)
        .map(|i| columns.iter().map(|column| column[i]).collect())
        .collect();
    Ok(Design {
        names,
        rows,
        strata,
        offset,
    })
}

impl Design {
    /// Prepend R's `(Intercept)` column of ones.
    fn with_intercept(mut self) -> Self {
        self.names.insert(0, "(Intercept)".to_string());
        for row in &mut self.rows {
            row.insert(0, 1.0);
        }
        self
    }
}

/// R keeps an intercept unless the formula removes it with `- 1` or `+ 0`.
fn formula_has_intercept(formula: &str) -> bool {
    let rhs: String = formula
        .split_once('~')
        .map(|(_, rhs)| rhs)
        .unwrap_or("")
        .chars()
        .filter(|c| !c.is_whitespace())
        .collect();
    !(rhs.contains("-1") || rhs == "0" || rhs.starts_with("0+") || rhs.contains("+0"))
}

fn complete_rows(response: &Response, design: &Design, extra: &[Option<&[f64]>]) -> Vec<usize> {
    (0..response.time.len())
        .filter(|&i| {
            response.time[i].is_finite()
                && response.start.as_ref().is_none_or(|s| s[i].is_finite())
                && design.rows[i].iter().all(|v| v.is_finite())
                && design.strata.as_ref().is_none_or(|s| s[i] >= 0)
                && design.offset.as_ref().is_none_or(|o| o[i].is_finite())
                && extra
                    .iter()
                    .all(|column| column.is_none_or(|c| c[i].is_finite()))
        })
        .collect()
}

fn pick<T: Copy>(values: &[T], rows: &[usize]) -> Vec<T> {
    rows.iter().map(|&i| values[i]).collect()
}

fn arg_nums(case: &Value, name: &str) -> Option<Vec<f64>> {
    let value = &case["args"][name];
    if value.is_null() {
        None
    } else {
        nums(value).ok()
    }
}

// ---------------------------------------------------------------------------
// survfit_km: Kaplan-Meier curves
// ---------------------------------------------------------------------------

fn km_config(case: &Value) -> Result<KaplanMeierConfig, String> {
    let args = &case["args"];
    for key in [
        "type",
        "stype",
        "ctype",
        "conf.lower",
        "start.time",
        "cluster",
        "id",
        "time0",
    ] {
        if !args[key].is_null() {
            return unsupported(format!("survfit argument {key}"));
        }
    }
    let conf_type = match text(&args["conf.type"]) {
        None | Some("log") => "log",
        Some("log-log") => "log-log",
        Some("plain") => "plain",
        Some(other) => return unsupported(format!("conf.type {other}")),
    };
    let conf_level = args["conf.int"].as_f64().unwrap_or(0.95);
    KaplanMeierConfig::create(None, None, Some(conf_level), Some(conf_type.to_string()))
        .map_err(|err| format!("config: {err:?}"))
}

fn check_km_curve(output: &SurvFitKMOutput, curve: &Value, aspect: &str) -> Result<(), String> {
    let path = format!("curve[{}]", text(&curve["name"]).unwrap_or("?"));
    let absent = |field: &str| curve[field].is_null();
    match aspect {
        "std_err" | "std_chaz" | "conf"
            if absent(if aspect == "conf" { "lower" } else { aspect }) =>
        {
            Ok(())
        }
        "time_counts" => {
            assert_vec(
                &output.time,
                &nums(&curve["time"])?,
                0.0,
                &format!("{path}.time"),
            )?;
            assert_vec(
                &output.n_risk,
                &nums(&curve["n_risk"])?,
                0.0,
                &format!("{path}.n_risk"),
            )?;
            assert_vec(
                &output.n_event,
                &nums(&curve["n_event"])?,
                0.0,
                &format!("{path}.n_event"),
            )?;
            assert_vec(
                &output.n_censor,
                &nums(&curve["n_censor"])?,
                0.0,
                &format!("{path}.n_censor"),
            )
        }
        "surv" => assert_vec(
            &output.estimate,
            &nums(&curve["surv"])?,
            RTOL_COEF,
            &format!("{path}.surv"),
        ),
        "std_err" => assert_vec(
            &output.std_err,
            &nums(&curve["std_err"])?,
            RTOL_VAR,
            &format!("{path}.std_err"),
        ),
        "cumhaz" => assert_vec(
            &output.cumhaz,
            &nums(&curve["cumhaz"])?,
            RTOL_COEF,
            &format!("{path}.cumhaz"),
        ),
        "std_chaz" => assert_vec(
            &output.std_chaz,
            &nums(&curve["std_chaz"])?,
            RTOL_VAR,
            &format!("{path}.std_chaz"),
        ),
        "conf" => {
            if curve["lower"].is_null() {
                return Ok(());
            }
            assert_vec(
                &output.conf_lower,
                &nums(&curve["lower"])?,
                RTOL_VAR,
                &format!("{path}.lower"),
            )?;
            assert_vec(
                &output.conf_upper,
                &nums(&curve["upper"])?,
                RTOL_VAR,
                &format!("{path}.upper"),
            )
        }
        other => unsupported(format!("aspect {other}")),
    }
}

