#[test]
fn r_fixtures_survfit_km() {
    let doc = load_topic("survfit_km");
    let mut report = Report::new("survfit_km");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let prepared = (|| -> Result<(Vec<SurvFitKMOutput>, Vec<Value>), String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let config = km_config(case)?;
            let response = response(formula, &frame)?;
            let weights = arg_nums(case, "weights").unwrap_or_else(|| vec![1.0; frame.nrow()]);
            let timefix = !matches!(case["args"]["timefix"].as_bool(), Some(false));
            let terms = rhs_terms(formula);
            let groups: Vec<(String, Vec<usize>)> = match terms.as_slice() {
                [term] if term == "1" => vec![("1".to_string(), (0..frame.nrow()).collect())],
                [term] => groups_by_column(frame.get(term)?),
                _ => return unsupported("harness: survfit with several grouping terms"),
            };
            let curves = case["expected"]["fit"]["curves"]
                .as_array()
                .ok_or("no curves")?;
            if curves.len() != groups.len() {
                return Err(format!(
                    "{} R curves but {} groups",
                    curves.len(),
                    groups.len()
                ));
            }
            let outputs: Vec<_> = groups
                .iter()
                .map(|(_, rows)| {
                    let status: Vec<f64> = pick(&response.status, rows)
                        .into_iter()
                        .map(f64::from)
                        .collect();
                    let entry = response.start.as_ref().map(|start| pick(start, rows));
                    compute_survfitkm_with_timefix(
                        &pick(&response.time, rows),
                        &status,
                        &pick(&weights, rows),
                        entry.as_deref(),
                        &vec![0; rows.len()],
                        &config,
                        timefix,
                    )
                })
                .collect();
            Ok((outputs, curves.clone()))
        })();
        match prepared {
            Err(message) => {
                for aspect in KM_ASPECTS {
                    report.record(name, aspect, Err(message.clone()));
                }
            }
            Ok((outputs, curves)) => {
                for aspect in KM_ASPECTS {
                    let result = outputs
                        .iter()
                        .zip(&curves)
                        .try_for_each(|(output, curve)| check_km_curve(output, curve, aspect));
                    report.record(name, aspect, result);
                }
            }
        }
    }
    report.finish();
}

