// survdiff
// ---------------------------------------------------------------------------

#[test]
fn r_fixtures_survdiff() {
    let doc = load_topic("survdiff");
    let mut report = Report::new("survdiff");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let result = (|| -> Result<_, String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let response = response(formula, &frame)?;
            if response.start.is_some() {
                return unsupported("counting-process survdiff");
            }
            let mut group_term = None;
            let mut strata_term = None;
            for term in rhs_terms(formula) {
                if let Some(inner) = term
                    .strip_prefix("strata(")
                    .and_then(|t| t.strip_suffix(')'))
                {
                    strata_term = Some(inner.to_string());
                } else if term.starts_with("offset(") {
                    return unsupported("one-sample survdiff against survexp");
                } else if group_term.replace(term).is_some() {
                    return unsupported("harness: several grouping terms");
                }
            }
            let group_column = frame.get(&group_term.ok_or("no group term")?)?;
            let group_levels = group_column.levels();
            let mut rows: Vec<usize> = (0..frame.nrow())
                .filter(|&i| group_column.label(i).is_some() && response.time[i].is_finite())
                .collect();
            let strata_codes: Option<Vec<i32>> = match &strata_term {
                Some(term) => {
                    let column = frame.get(term)?;
                    let levels = column.levels();
                    rows.retain(|&i| column.label(i).is_some());
                    rows.sort_by_key(|&i| {
                        levels
                            .iter()
                            .position(|l| Some(l.as_str()) == column.label(i).as_deref())
                    });
                    let codes: Vec<i32> = rows
                        .iter()
                        .map(|&i| {
                            levels
                                .iter()
                                .position(|l| Some(l.as_str()) == column.label(i).as_deref())
                                .map_or(0, |p| p as i32)
                        })
                        .collect();
                    // stratum end markers
                    Some(
                        (0..codes.len())
                            .map(|k| i32::from(k + 1 == codes.len() || codes[k + 1] != codes[k]))
                            .collect(),
                    )
                }
                None => None,
            };
            let group: Vec<i32> = rows
                .iter()
                .map(|&i| {
                    group_levels
                        .iter()
                        .position(|l| Some(l.as_str()) == group_column.label(i).as_deref())
                        .map_or(0, |p| p as i32 + 1)
                })
                .collect();
            let rho = case["args"]["rho"].as_f64();
            let fit = survdiff2(
                pick(&response.time, &rows),
                pick(&response.status, &rows),
                group,
                strata_codes,
                rho,
                Some(true),
            )
            .map_err(|err| format!("survdiff2: {err:?}"))?;
            Ok(fit)
        })();
        let expected = &case["expected"];
        match result {
            Err(message) => {
                for aspect in ["counts", "var", "chisq"] {
                    report.record(name, aspect, Err(message.clone()));
                }
            }
            Ok(fit) => {
                let counts = (|| {
                    // With strata R reports group x stratum matrices; the kernel
                    // returns the totals over strata.
                    let totals = |value: &Value| -> Result<Vec<f64>, String> {
                        if value
                            .as_array()
                            .is_some_and(|v| v.first().is_some_and(Value::is_array))
                        {
                            Ok(matrix(value)?.iter().map(|row| row.iter().sum()).collect())
                        } else {
                            nums(value)
                        }
                    };
                    assert_vec(&fit.observed, &totals(&expected["obs"])?, 1e-12, "obs")?;
                    assert_vec(&fit.expected, &totals(&expected["exp"])?, RTOL_COEF, "exp")
                })();
                report.record(name, "counts", counts);
                let var = (|| {
                    let expected_var = &expected["var"];
                    if expected_var
                        .as_array()
                        .is_some_and(|v| v.first().is_some_and(Value::is_array))
                    {
                        assert_matrix(&fit.variance, &matrix(expected_var)?, RTOL_VAR, "var")
                    } else {
                        let flat: Vec<f64> = fit.variance.iter().flatten().copied().collect();
                        assert_vec(&flat, &nums(expected_var)?, RTOL_VAR, "var")
                    }
                })();
                report.record(name, "var", var);
                let chisq = (|| {
                    assert_scalar(fit.chi_squared, num(&expected["chisq"])?, RTOL_VAR, "chisq")
                })();
                report.record(name, "chisq", chisq);
            }
        }
    }
    report.finish();
}

