#[test]
fn r_fixtures_survreg() {
    let doc = load_topic("survreg");
    let mut report = Report::new("survreg");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        if name == "distribution_functions" {
            continue;
        }
        let expected = &case["expected"];
        let fit = (|| -> Result<_, String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let args = &case["args"];
            for key in ["init", "robust", "x", "parms"] {
                if !args[key].is_null() {
                    return unsupported(format!("survreg argument {key}"));
                }
            }
            let response = response(formula, &frame)?;
            if response.start.is_some() {
                return unsupported("counting-process survreg");
            }
            // R's survreg fits an intercept (the kernel takes the design
            // matrix as given), so add the column of ones R would.
            let mut design = design(formula, &frame)?;
            if formula_has_intercept(formula) {
                design = design.with_intercept();
            }
            if design.offset.is_some() {
                return unsupported("offset");
            }
            let weights = arg_nums(case, "weights");
            let rows = complete_rows(&response, &design, &[weights.as_deref()]);
            let strata = design.strata.as_ref().map(|s| {
                pick(s, &rows)
                    .into_iter()
                    .map(|code| code as usize)
                    .collect::<Vec<usize>>()
            });
            let dist = text(&args["dist"]).unwrap_or("weibull");
            let fixed_scale = args["scale"].as_f64().filter(|s| *s > 0.0);
            let fit = survreg(
                pick(&response.time, &rows),
                pick(&response.status, &rows)
                    .into_iter()
                    .map(f64::from)
                    .collect(),
                rows.iter().map(|&i| design.rows[i].clone()).collect(),
                weights.as_ref().map(|w| pick(w, &rows)),
                None,
                None,
                strata,
                Some(dist),
                None,
                None,
                None,
                None,
                fixed_scale,
                None,
            )
            .map_err(|err| format!("survreg: {err:?}"))?;
            Ok(fit)
        })();
        let aspects = ["coef", "scale", "loglik", "var", "linear_predictors"];
        match fit {
            Err(message) => {
                for aspect in aspects {
                    report.record(name, aspect, Err(message.clone()));
                }
            }
            Ok(fit) => {
                // R's coef is the location part only ((Intercept), terms...);
                // the scale is reported separately.
                report.record(
                    name,
                    "coef",
                    (|| {
                        assert_vec(
                            &fit.location_coefficients,
                            &named_values(&expected["coef"], &expected["coef_names"])?,
                            RTOL_COEF,
                            "coef",
                        )
                    })(),
                );
                report.record(
                    name,
                    "scale",
                    (|| {
                        let scales = nums(&expected["scale"])?;
                        if scales.len() == 1 {
                            assert_scalar(fit.scale, scales[0], RTOL_COEF, "scale")
                        } else {
                            assert_vec(&fit.scales, &scales, RTOL_COEF, "scale")
                        }
                    })(),
                );
                report.record(
                    name,
                    "loglik",
                    (|| {
                        let loglik = nums(&expected["loglik"])?;
                        assert_scalar(fit.log_likelihood, loglik[1], RTOL_COEF, "loglik")
                    })(),
                );
                report.record(
                    name,
                    "var",
                    (|| {
                        // R's var is the full (coefficients, Log(scale) per
                        // stratum) block; the kernel lays it out the same way.
                        assert_matrix(
                            &fit.variance_matrix,
                            &matrix(&expected["var"])?,
                            RTOL_VAR,
                            "var",
                        )
                    })(),
                );
                report.record(
                    name,
                    "linear_predictors",
                    (|| {
                        assert_vec(
                            &fit.linear_predictors,
                            &nums(&expected["linear_predictors"])?,
                            RTOL_COEF,
                            "linear_predictors",
                        )
                    })(),
                );
            }
        }
    }
    report.finish();
}

// ---------------------------------------------------------------------------
// concordance (right-censored, single numeric score)
// ---------------------------------------------------------------------------

#[test]
fn r_fixtures_concordance() {
    use crate::concordance::basic::{concordance_index, counting_concordance_index};
    let doc = load_topic("concordance");
    let mut report = Report::new("concordance");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        let result = (|| -> Result<(), String> {
            if expected["coxph"].is_object() {
                return unsupported("concordance of fitted models");
            }
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let args = &case["args"];
            for key in ["ranks", "influence"] {
                if !args[key].is_null() {
                    return unsupported(format!("concordance_index has no {key} output"));
                }
            }
            if !formula.trim_start().starts_with("Surv(") {
                return unsupported("harness: numeric (uncensored) response");
            }
            let response = response(formula, &frame)?;
            let terms = rhs_terms(formula);
            let score_term = match terms.as_slice() {
                [term] if !term.starts_with("strata(") => term.clone(),
                _ => return unsupported("harness: several terms or strata"),
            };
            if score_term.contains('(') {
                return unsupported(format!("harness: term {score_term}"));
            }
            let scores = frame.get(&score_term)?.numeric(&score_term)?;
            let weights = arg_nums(case, "weights");
            let rows: Vec<usize> = (0..frame.nrow())
                .filter(|&i| scores[i].is_finite() && response.time[i].is_finite())
                .collect();
            let reverse = is_true(&args["reverse"]);
            let timewt = text(&args["timewt"]).unwrap_or("n").to_string();
            // R's default is concordance of y with x; reverse = TRUE treats x
            // as a risk score, which is what concordance_index computes.
            let risk: Vec<f64> = pick(&scores, &rows)
                .into_iter()
                .map(|s| if reverse { s } else { -s })
                .collect();
            let actual = match &response.start {
                Some(start) => counting_concordance_index(
                    pick(start, &rows),
                    pick(&response.time, &rows),
                    pick(&response.status, &rows),
                    risk,
                    weights.map(|w| pick(&w, &rows)),
                    timewt,
                    Some(true),
                )
                .map_err(|err| format!("counting_concordance_index: {err:?}"))?,
                None => concordance_index(
                    pick(&response.time, &rows),
                    pick(&response.status, &rows),
                    risk,
                    weights.map(|w| pick(&w, &rows)),
                    timewt,
                )
                .map_err(|err| format!("concordance_index: {err:?}"))?,
            };
            assert_scalar(
                actual,
                nums(&expected["concordance"])?[0],
                RTOL_COEF,
                "concordance",
            )
        })();
        report.record(name, "concordance", result);
    }
    report.finish();
}

